Method.Source:
    /// <summary>
    /// initialises the overview values for temp table
    /// </summary>
    /// <param name = "_wmsArrivalOverviewTmp">Arrival overview temp table</param>
    /// <param name = "_dateStatus">Trans date</param>
    /// <param name = "_inventTransType">Trans type ref</param>
    /// <param name = "_inventTransRefId">Reference Id</param>
    /// <param name = "_inventSiteId">Site id</param>
    /// <param name = "_inventLocationId">Location id</param>
    protected void initOverviewValues(
        WMSArrivalOverviewTmp   _wmsArrivalOverviewTmp,
        DateStatus              _dateStatus,
        InventTransType         _inventTransType,
        InventTransRefId        _inventTransRefId,
        InventSiteId            _inventSiteId,
        InventLocationId        _inventLocationId)
    {
        PurchTable  purchTable;

        next initOverviewValues(_wmsArrivalOverviewTmp, _dateStatus, _inventTransType, _inventTransRefId, _inventSiteId, _inventLocationId);

        switch (_inventTransType)
        {
            case InventTransType::Purch:
                purchTable = this.parmInventTransRefBuffer();
                if (!purchTable)
                {
                    purchTable = this.parmInventTransRefBuffer(PurchTable::find(_inventTransRefId));
                }

                _wmsArrivalOverviewTmp.METPOYardDAppointmentStartDateTime = purchTable.metPurchTable().POYardDAppointmentStartDateTime;
                _wmsArrivalOverviewTmp.METPOYardDAppointmentEndDateTime   = purchTable.metPurchTable().POYardDAppointmentEndDateTime;

                break;
        }
    }

    /// <summary>
    /// initialises the details values
    /// </summary>
    /// <param name = "_wmsArrivalDetailTmp">Arrival details temp table</param>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_initWeightAndVolume">Boolean value to indicate whether to initialise weight and volume</param>
    protected void initDetailValues(
        WMSArrivalDetailTmp _wmsArrivalDetailTmp,
        ItemId              _itemId,
        boolean             _initWeightAndVolume)
    {
        PurchLine purchLine;

        next initDetailValues(_wmsArrivalDetailTmp, _itemId, _initWeightAndVolume);

        switch (_wmsArrivalDetailTmp.InventTransType)
        {
            case InventTransType::Purch:
                purchLine = PurchLine::findInventTransId(_wmsArrivalDetailTmp.InventTransId);

                _wmsArrivalDetailTmp.METUnitId = purchLine.PurchUnit;

                break;
        }

    }
